{
  "command": "git diff -U5 -- launcher/mse_project_menu.pyw launcher/setup_mse.py .script/release_package.py tests/test_mse_project_menu.py tests/test_english_source_of_truth.py tests/test_release_package.py docs/MSE.md README.md docs/CONTEXT.md website/src/components/Navigation.svelte website/src/layouts/BaseLayout.astro website/src/styles/global.css website/tests/e2e/showcase.spec.ts",
