{
  "command": "git status --short -- website/dist website/src/content.config.ts website/src/generated 2>/dev/null || true; git status --short | tail -40",
  "timeout": 20
}

{
  "command": "python - <<'PY'
from pathlib import Path
bad=[]
titles=[]
for p in sorted(Path('cards_mse').glob('**/*.mse-set/set')):
    lines=p.read_text(encoding='utf-8-sig').splitlines()
    title=next((x.split(':',1)[1].strip() for x in lines if x.lstrip().startswith('title:')),None)
    titles.append((str(p),title))
    if not title or not title.startswith('Essentia -- '): bad.append((str(p),title))
print(f'checked={len(titles)} bad={len(bad)}')
for item in bad: print(item)
PY",
  "timeout": 30
}
